'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');

const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v8.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v9.js');
const meshCss=read('docs/scifi-ui/styles/formatx-core-mesh3d.css');
const apex=read('docs/scifi-ui/scripts/formatx-apex-native.js');
const voice=read('docs/scifi-ui/scripts/organism-voice-stability.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');

assert.match(mapper,/fxApexSceneStability='ready-v17'/,'v9 production mapper missing');
assert.match(mapper,/formatx-core-mesh3d-v8\.js\?v=20260808-true-mesh3d-v8/,'v8 true mesh bootstrap missing');
assert.match(mapper,/formatx-core-fracture3d-v9\.js\?v=20260808-fracture3d-v9/,'v9 fracture bootstrap missing');
assert.match(mapper,/if\(uScene<\.92\)return vec2\(10\.,1\.\)/,'legacy SDF MAG suppression missing');
assert.match(mapper,/retired-for-real-3d-reactor/,'screen-space reactor retirement missing');
assert.match(mapper,/reference-two-sided-fractured-true-mesh3d-v18/,'true 3D visual marker missing');
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/,'mapper must not capture scrolling');

assert.match(mesh,/getContext\('webgl2'/,'WebGL2 mesh context missing');
assert.match(mesh,/depth:true/,'mesh depth buffer missing');
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/,'mesh depth testing missing');
assert.match(mesh,/gl\.enable\(gl\.CULL_FACE\)/,'mesh face culling missing');
assert.match(mesh,/gl\.cullFace\(gl\.FRONT\)/,'mesh back-face pass missing');
assert.match(mesh,/gl\.cullFace\(gl\.BACK\)/,'mesh front-face pass missing');
assert.match(mesh,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'mesh index buffer missing');
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangle rendering missing');
assert.match(mesh,/aPosition/,'vertex positions missing');
assert.match(mesh,/aNormal/,'vertex normals missing');
assert.match(mesh,/cross\(dFdx\(vP\),dFdy\(vP\)\)/,'faceted derivative normal missing');
assert.match(mesh,/uProjection\*uView\*vec4\(p,1\.\)/,'perspective projection missing');
assert.match(mesh,/\[0,1\],\[\.10,\.77\],\[\.28,\.42\],\[\.66,\.12\]/,'reference four-tip contour missing');
assert.match(mesh,/dep=\.34/,'real Z depth missing');
assert.match(mesh,/ys=1\.18/,'reference vertical aspect missing');
assert.match(mesh,/fc=add\(0,0,dep\)/,'front surface missing');
assert.match(mesh,/bc=add\(0,0,-dep\)/,'back surface missing');
assert.match(mesh,/of=fr\[R-1\],ob=br\[R-1\]/,'side wall geometry missing');
assert.match(mesh,/tri\(crystal,0,\.455,pulse/,'inner real glass mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.505,pulse/,'middle real glass mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.550,pulse/,'main real glass mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.562,pulse/,'outer Fresnel mesh pass missing');
assert.match(mesh,/core=up\(sphere\(\.080\)\)/,'real reactor sphere missing');
assert.match(mesh,/up\(torus\(\.34,\.006\)\)/,'real inner reactor torus missing');
assert.match(mesh,/up\(torus\(\.50,\.0055\)\)/,'real middle reactor torus missing');
assert.match(mesh,/up\(torus\(\.66,\.005\)\)/,'real outer reactor torus missing');
assert.match(mesh,/hBeam=up\(box\(1\.15,\.007,\.006\)\)/,'real horizontal flare geometry missing');
assert.match(mesh,/vBeam=up\(box\(\.007,1\.28,\.006\)\)/,'real vertical flare geometry missing');
assert.match(mesh,/fxCoreMesh3d='ready-v8'/,'v8 mesh ready marker missing');
assert.match(mesh,/fxCoreGeometry='indexed-triangle-mesh-v8'/,'v8 indexed mesh marker missing');
assert.match(mesh,/fxCoreGlassPass='two-sided-back-front'/,'two-sided glass marker missing');
assert.match(mesh,/fxCoreReactorGeometry='sphere-plus-3-tori-plus-2-box-beams'/,'real reactor geometry marker missing');
assert.doesNotMatch(mesh,/drawImage\s*\(|new Image\s*\(|background-image/i,'MAG must not be image-backed');
assert.doesNotMatch(mesh,/THREE\b|three\.js|gsap/i,'third-party scene framework forbidden');

assert.match(fracture,/getContext\('webgl2'/,'fracture WebGL2 context missing');
assert.match(fracture,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'fracture index buffer missing');
assert.match(fracture,/gl\.drawElements\(gl\.LINES/,'fracture must use indexed GL_LINES');
assert.match(fracture,/point\(r1,i1,\.008\)/,'fracture segments must lie on the 3D crystal surface');
assert.match(fracture,/uProjection\*uView\*vec4\(p,1\.\)/,'fracture perspective projection missing');
assert.match(fracture,/uRotation/,'fracture 3D rotation missing');
assert.match(fracture,/uPulse/,'fracture living pulse missing');
assert.match(fracture,/fxCoreFracture3d='ready-v9'/,'fracture ready marker missing');
assert.match(fracture,/fxCoreFractureGeometry='indexed-gl-lines'/,'fracture geometry marker missing');
assert.doesNotMatch(fracture,/drawImage\s*\(|new Image\s*\(|background-image/i,'fracture network must not be image-backed');

assert.match(meshCss,/pointer-events: none/,'mesh must not capture input');
assert.match(meshCss,/height: 100dvh/,'dynamic viewport missing');
assert.match(apex,/quality: coarse\.matches \? 0\.82 : 0\.88/,'Apex background quality regressed');
assert.match(voice,/window\.visualViewport/,'dialogue viewport guard missing');
assert.match(voice,/keyboardInset/,'keyboard inset guard missing');
assert.match(infinite,/const VERSION = 'seamless-v7'/,'seamless-v7 regressed');
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/,'native momentum regressed');

console.log('PASS: production MAG uses real two-sided indexed WebGL2 geometry plus a surface-attached indexed 3D fracture network; no 2D MAG/reac tor ownership and seamless-v7 remains intact.');
